    prev_openBtn : BOOL;
    prev_closeBtn: BOOL;
    prev_obstacle: BOOL;
END_VAR

// 边沿检测
openRising  := openBtn AND NOT prev_openBtn;
closeRising := closeBtn AND NOT prev_closeBtn;
obstacleRising := obstacle AND NOT prev_obstacle;

