            state := 1;  // OPENING
        ELSIF closeRising AND NOT closeLimit THEN
            state := 2;  // CLOSING
        END_IF

    // OPENING状态
    1:  // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;

        IF obstacleRising THEN
            state := 3;  // FAULT
            errorFlag := TRUE;
        ELSIF openLimit THEN
            state := 0;  // 返回IDLE
        END_IF

